fn main() -> Int {
  let leaderboard: Vec[Int] = Vec[Int].new();
  leaderboard.push(950); leaderboard.push(880);

  let profiles: Map[Str,Str] = Map[Str,Str].new();
  profiles.insert("alice", "alice@email.com");

  let banned: Set[Str] = Set[Str].new();
  banned.insert("spam"); banned.insert("scam");

  io.println("Leaderboard entries: " + string.int_to_str(leaderboard.len()));
  match profiles.get("alice") {
    Some(email) -> io.println("Alice: " + email);
    None -> io.println("Not found");
  }
  io.println(banned.contains("spam"));
  return 0;
}
