use xiom.io;
fn main() -> Int {
  let temps: Vec[Int] = Vec[Int].new();
  temps.push(72); temps.push(68); temps.push(75);

  let populations: Map[Str,Int] = Map[Str,Int].new();
  populations.insert("Monaco", 39000);

  let admins: Set[Str] = Set[Str].new();
  admins.insert("alice"); admins.insert("bob");

  io.println(temps.len().to_str());

  match populations.get("Monaco") {
    Some(p) => io.println(p.to_str());
    None => io.println("no data");
  }

  io.println(admins.contains("alice").to_str());
  return 0;
}
